def transform(grid):
    h,w=len(grid),len(grid[0]); out=[r[:] for r in grid]
    # Denoise the 5 repeated 2-pixel panels with a 3x3 majority filter,
    # treating the separator columns as fixed background.
    for r in range(h):
        for c in range(w):
            if c%3==2: continue
            vals=[]
            for dr in (-1,0,1):
                for dc in (-1,0,1):
                    rr,cc=r+dr,c+dc
                    if 0<=rr<h and 0<=cc<w and cc%3!=2: vals.append(grid[rr][cc])
            if vals.count(0)>len(vals)/2: out[r][c]=0
            elif vals.count(0)<len(vals)/2: out[r][c]=grid[r][0]
    return out
